begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select extensions.no_plan();
insert into auth.users(id,email) values('11111111-1111-4111-8111-111111111111','event-a@example.invalid'),('22222222-2222-4222-8222-222222222222','event-b@example.invalid');
select extensions.ok(not has_function_privilege('anon','public.apply_event_operation(uuid,text,text,text,text,uuid,jsonb,integer)','EXECUTE'),'anon event writer denied');
select extensions.ok(has_function_privilege('authenticated','public.apply_event_operation(uuid,text,text,text,text,uuid,jsonb,integer)','EXECUTE'),'authenticated event capability');
select extensions.ok((select prosecdef and proowner='pickleup_api'::regrole and proconfig @> array['search_path=""'] from pg_proc where oid='public.apply_event_operation(uuid,text,text,text,text,uuid,jsonb,integer)'::regprocedure),'event writer narrow owner and empty search path');
select extensions.ok((select not rolcanlogin and not rolbypassrls from pg_roles where rolname='pickleup_api'),'API role no login/no bypass');
select extensions.ok(not has_table_privilege('pickleup_api','pickleup_private.sync_operation_epochs','UPDATE,DELETE'),'event epoch ledger stays append-only');
set local role authenticated;
select set_config('request.jwt.claims','{"sub": "11111111-1111-4111-8111-111111111111", "role": "authenticated"}',true);
select set_config('test.event_epoch',public.prepare_sync()->>'epoch',true);
select extensions.is(public.apply_event_operation('33333333-3333-4333-8333-333333333333','academy_attempts','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','put','0',current_setting('test.event_epoch')::uuid,'{"client_event_id": "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa", "lesson_id": "PU-001", "skill": "serve", "level_band": "1.0–2.0", "score": 12, "occurred_at": "2026-01-01T10:00:00Z", "content_version": "test-1", "lesson_snapshot": {"title": "Synthetic serve"}, "conditions": null}'::jsonb,2)->>'status','upgrade_required','wire protocol checked');
select extensions.is(public.apply_event_operation('33333333-3333-4333-8333-333333333333','academy_attempts','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','put','0','44444444-4444-4444-8444-444444444444'::uuid,'{"client_event_id": "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa", "lesson_id": "PU-001", "skill": "serve", "level_band": "1.0–2.0", "score": 12, "occurred_at": "2026-01-01T10:00:00Z", "content_version": "test-1", "lesson_snapshot": {"title": "Synthetic serve"}, "conditions": null}'::jsonb,1)->>'status','reset_required','wrong epoch cannot append');
select extensions.is(public.apply_event_operation('33333333-3333-4333-8333-333333333333','academy_attempts','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','put','0',current_setting('test.event_epoch')::uuid,'{"client_event_id": "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa", "lesson_id": "PU-001", "skill": "serve", "level_band": "1.0–2.0", "score": 12, "occurred_at": "2026-01-01T10:00:00Z", "content_version": "test-1", "lesson_snapshot": {"title": "Synthetic serve"}, "conditions": null}'::jsonb,1)->>'status','applied','first event appended');
select extensions.is(public.apply_event_operation('33333333-3333-4333-8333-333333333333','academy_attempts','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','put','0',current_setting('test.event_epoch')::uuid,'{"client_event_id": "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa", "lesson_id": "PU-001", "skill": "serve", "level_band": "1.0–2.0", "score": 12, "occurred_at": "2026-01-01T10:00:00Z", "content_version": "test-1", "lesson_snapshot": {"title": "Synthetic serve"}, "conditions": null}'::jsonb,1)->>'replayed','true','same request replay once');
select extensions.is(public.apply_event_operation('33333333-3333-4333-8333-333333333333','academy_attempts','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','put','0',current_setting('test.event_epoch')::uuid,'{"client_event_id": "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa", "lesson_id": "PU-001", "skill": "serve", "level_band": "1.0–2.0", "score": 13, "occurred_at": "2026-01-01T10:00:00Z", "content_version": "test-1", "lesson_snapshot": {"title": "Synthetic serve"}, "conditions": null}'::jsonb,1)->>'code','operation_id_reused','event request body immutable');
select extensions.is(public.apply_event_operation('55555555-5555-4555-8555-555555555555','academy_attempts','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','put','1',current_setting('test.event_epoch')::uuid,'{"client_event_id": "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa", "lesson_id": "PU-001", "skill": "serve", "level_band": "1.0–2.0", "score": 12, "occurred_at": "2026-01-01T10:00:00Z", "content_version": "test-1", "lesson_snapshot": {"title": "Synthetic serve"}, "conditions": null}'::jsonb,1)->>'status','invalid','existing event content cannot update');
select extensions.is(public.apply_event_operation('66666666-6666-4666-8666-666666666666','academy_attempts','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','put','0',current_setting('test.event_epoch')::uuid,'{"client_event_id": "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa", "lesson_id": "PU-001", "skill": "serve", "level_band": "1.0–2.0", "score": 12, "occurred_at": "2026-01-01T10:00:00Z", "content_version": "test-1", "lesson_snapshot": {"title": "Synthetic serve"}, "conditions": null}'::jsonb,1)->>'status','invalid','client event UUID unique per owner');
select extensions.is(public.apply_event_operation('77777777-7777-4777-8777-777777777777','user_preferences','self','put','0',current_setting('test.event_epoch')::uuid,'{"client_event_id": "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa", "lesson_id": "PU-001", "skill": "serve", "level_band": "1.0–2.0", "score": 12, "occurred_at": "2026-01-01T10:00:00Z", "content_version": "test-1", "lesson_snapshot": {"title": "Synthetic serve"}, "conditions": null}'::jsonb,1)->>'status','invalid','event capability excludes mutable domains');
select extensions.is(public.apply_event_operation('88888888-8888-4888-8888-888888888888','academy_attempts','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',null,'0',current_setting('test.event_epoch')::uuid,'{"client_event_id": "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa", "lesson_id": "PU-001", "skill": "serve", "level_band": "1.0–2.0", "score": 12, "occurred_at": "2026-01-01T10:00:00Z", "content_version": "test-1", "lesson_snapshot": {"title": "Synthetic serve"}, "conditions": null}'::jsonb,1)->>'status','invalid','null action rejected');
select extensions.is(public.apply_event_operation('88888888-8888-4888-8888-888888888888','academy_attempts','AAAAAAAA-AAAA-4AAA-8AAA-AAAAAAAAAAAA','put','0',current_setting('test.event_epoch')::uuid,'{"client_event_id": "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa", "lesson_id": "PU-001", "skill": "serve", "level_band": "1.0–2.0", "score": 12, "occurred_at": "2026-01-01T10:00:00Z", "content_version": "test-1", "lesson_snapshot": {"title": "Synthetic serve"}, "conditions": null}'::jsonb,1)->>'status','invalid','canonical UUID entity key required');
select extensions.is(public.apply_event_operation('88888888-8888-4888-8888-888888888888','academy_attempts','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','put','0',current_setting('test.event_epoch')::uuid,'{"client_event_id": "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa", "lesson_id": "PU-001", "skill": "serve", "level_band": "1.0–2.0", "score": 12, "occurred_at": "2026-01-01T10:00:00Z", "content_version": "test-1", "lesson_snapshot": {"title": "Synthetic serve"}, "conditions": null, "user_id": "22222222-2222-4222-8222-222222222222"}'::jsonb,1)->>'status','invalid','owner field cannot be assigned');
select extensions.is((select count(*)::text from public.practice_checkins),'0','events never create attendance');
select extensions.is(public.apply_event_operation('99999999-9999-4999-8999-999999999999','academy_attempts','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','delete','1',current_setting('test.event_epoch')::uuid,'{}'::jsonb,1)->>'status','applied','event delete is CAS tombstone');
select extensions.is(public.apply_event_operation('88888888-8888-4888-8888-888888888888','academy_attempts','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','restore','2',current_setting('test.event_epoch')::uuid,'{"client_event_id": "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa", "lesson_id": "PU-001", "skill": "serve", "level_band": "1.0–2.0", "score": 12, "occurred_at": "2026-01-01T10:00:00Z", "content_version": "test-1", "lesson_snapshot": {"title": "Synthetic serve"}, "conditions": null}'::jsonb,1)->>'status','invalid','event tombstone cannot restore');
select extensions.is((select revision::text from public.academy_attempts),'2','rejected writes leave event revision unchanged');
select set_config('request.jwt.claims','{"sub": "22222222-2222-4222-8222-222222222222", "role": "authenticated"}',true);
select extensions.is((select count(*)::text from public.academy_attempts),'0','B sees no A events');
select set_config('test.event_epoch_b',public.prepare_sync()->>'epoch',true);
select extensions.is(public.apply_event_operation('33333333-3333-4333-8333-333333333333','academy_attempts','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','put','0',current_setting('test.event_epoch_b')::uuid,'{"client_event_id": "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa", "lesson_id": "PU-001", "skill": "serve", "level_band": "1.0–2.0", "score": 12, "occurred_at": "2026-01-01T10:00:00Z", "content_version": "test-1", "lesson_snapshot": {"title": "Synthetic serve"}, "conditions": null}'::jsonb,1)->>'status','applied','same event/operation UUID independent for B');
reset role;
update pickleup_private.sync_heads set epoch='eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee' where user_id='11111111-1111-4111-8111-111111111111';
set local role authenticated;
select set_config('request.jwt.claims','{"sub": "11111111-1111-4111-8111-111111111111", "role": "authenticated"}',true);
select extensions.is(public.apply_event_operation('33333333-3333-4333-8333-333333333333','academy_attempts','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','put','0',current_setting('test.event_epoch')::uuid,'{"client_event_id": "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa", "lesson_id": "PU-001", "skill": "serve", "level_band": "1.0–2.0", "score": 12, "occurred_at": "2026-01-01T10:00:00Z", "content_version": "test-1", "lesson_snapshot": {"title": "Synthetic serve"}, "conditions": null}'::jsonb,1)->>'status','reset_required','epoch restore blocks replay before old receipt');
select extensions.is(public.apply_event_operation('33333333-3333-4333-8333-333333333333','academy_attempts','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','put','0','eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee'::uuid,'{"client_event_id": "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa", "lesson_id": "PU-001", "skill": "serve", "level_band": "1.0–2.0", "score": 12, "occurred_at": "2026-01-01T10:00:00Z", "content_version": "test-1", "lesson_snapshot": {"title": "Synthetic serve"}, "conditions": null}'::jsonb,1)->>'code','operation_epoch_mismatch','old event operation cannot rebind epoch');
reset role;
select * from extensions.finish();
rollback;
